private Meshes.MeshAccessor<EpicColoniesMesh> resolveMeshAccessor(E citizen) {
    Meshes.MeshAccessor<EpicColoniesMesh> childMesh;
    ICitizenDataView view = citizen.getCitizenDataView();
    boolean female = citizen.isFemale();
    Meshes.MeshAccessor<EpicColoniesMesh> defaultMesh = female ? EpicColoniesMeshes.DEFAULT_FEMALE : EpicColoniesMeshes.DEFAULT_MALE;
    Meshes.MeshAccessor<EpicColoniesMesh> meshAccessor = childMesh = !female ? EpicColoniesMeshes.CHILD_MALE : EpicColoniesMeshes.CHILD_FEMALE;
    if (view == null) {
        return defaultMesh;
    }
    IJobView jobView = view.getJobView();
    if ((jobView == null || jobView.getEntry() == null) && view.isChild()) {
        return childMesh;
    }
    return this.meshMap.getOrDefault(new Pair((Object)female, (Object)citizen.getModelType()), defaultMesh);
}

