@Mod.EventBusSubscriber(modid="epic_colonies", bus=Mod.EventBusSubscriber.Bus.FORGE, value={Dist.CLIENT})
public class DualSwordsRender
extends RenderItemBase {
    private final ItemStack swordStack;

    public DualSwordsRender(JsonElement jsonElement) {
        super(jsonElement);
        this.swordStack = jsonElement.getAsJsonObject().has("weapon") ? new ItemStack((ItemLike)Objects.requireNonNull((Item)ForgeRegistries.ITEMS.getValue(ResourceLocation.parse((String)jsonElement.getAsJsonObject().get("weapon").getAsString())))) : new ItemStack((ItemLike)EpicColoniesItems.IRON_DUAL_SWORDS.get());
    }

    public void renderItemInHand(ItemStack stack, LivingEntityPatch<?> entitypatch, InteractionHand hand, OpenMatrix4f[] poses, MultiBufferSource buffer, PoseStack poseStack, int packedLight, float partialTicks) {
        super.renderItemInHand(this.swordStack, entitypatch, InteractionHand.MAIN_HAND, poses, buffer, poseStack, packedLight, partialTicks);
        super.renderItemInHand(this.swordStack, entitypatch, InteractionHand.OFF_HAND, poses, buffer, poseStack, packedLight, partialTicks);
    }
}

