    for (String other : this.formBones.keySet()) {
        if (other.equals(this.form) || !this.formShown(other)) continue;
        EpicYsm.LOGGER.info("Skeleton overlay: the model switched from form '{}' to form '{}'; reading the skeleton again for that one", (Object)(this.form.isEmpty() ? "plain" : this.form), (Object)(other.isEmpty() ? "plain" : other));
        this.restore();
        this.reset();
        return false;
