    if (!this.dormant) {
        this.dormant = true;
        if (!this.saidDormant) {
            this.saidDormant = true;
            EpicYsm.LOGGER.info("Skeleton overlay: no human form of this model is on screen - it has turned into something else - so Yes Steve Model is left to animate it alone until a human form is back.");
