    public static final MenuType<ContainerActiveFormationPlane> TYPE = MenuTypeBuilder.create(ContainerActiveFormationPlane::new, PartActiveFormationPlane.class).build("active_formation_plane");
    @GuiSync(value=7)
    public YesNo placeMode;

    public ContainerActiveFormationPlane(int id, Inventory ip, PartActiveFormationPlane host) {
        super(TYPE, id, ip, (IUpgradeableObject)host);
    }

    protected void setupConfig() {
        this.addExpandableConfigSlots((GenericStackInv)((PartActiveFormationPlane)this.getHost()).getConfig(), 2, 9, 5);
    }

    protected void loadSettingsFromHost(IConfigManager cm) {
        if (this.supportsFuzzyRangeSearch()) {
            this.setFuzzyMode((FuzzyMode)cm.getSetting(Settings.FUZZY_MODE));
        }
        this.setPlaceMode((YesNo)cm.getSetting(Settings.PLACE_BLOCK));
    }

    public boolean isSlotEnabled(int idx) {
        int upgrades = this.getUpgrades().getInstalledUpgrades((ItemLike)AEItems.CAPACITY_CARD);
        return upgrades > idx;
    }

    public YesNo getPlaceMode() {
        return this.placeMode;
    }

    private void setPlaceMode(YesNo placeMode) {
        this.placeMode = placeMode;
    }

    public boolean supportsFuzzyMode() {
        return this.hasUpgrade((ItemLike)AEItems.FUZZY_CARD) && this.supportsFuzzyRangeSearch();
    }

    private boolean supportsFuzzyRangeSearch() {
        for (AEKey key : ((PartActiveFormationPlane)this.getHost()).getConfig().keySet()) {
            if (!key.supportsFuzzyRangeSearch()) continue;
            return true;
        }
        return false;
    }
}

